    result1 = df.agg(sum(col("val"))).collect()[0][0]
    df = spark.createDataFrame(data, "val double").repartition(num_partitions)
    result2 = df.agg(sum(col("val"))).collect()[0][0]
    assert result1 == result2, f"{result1}, {result2}"


