There are CSV files out there with multiple values that are supposed to be interpreted as null. Currently the `nullValue` option of spark.read is accepting only one value.

Can we come with something like below:
{code:java}
spark.read.option("nullValue1", "abc").option("nullValue2", "def").csv("1.csv")
{code}
Or
{code:java}
spark.read.option("nullValue", Seq("abc","def")).csv("1.csv") {code}
Where the values "abc" and "def" are to be interpreted as NULLs.

{code:java}
test("share messages with allGather() call") {  
  val conf = new SparkConf()
      .setMaster("local-cluster[4, 1, 1024]")
      .setAppName("test-cluster")
  sc = new SparkContext(conf)
  val rdd = sc.makeRDD(1 to 10, 4)
  val rdd2 = rdd.barrier().mapPartitions { it =>  
    val context = BarrierTaskContext.get()      
    // Sleep for a random time before global sync.
    Thread.sleep(Random.nextInt(1000))  
    // Pass partitionId message in
    val message: String = context.partitionId().toString
    val messages: Array[String] = context.allGather(message)
    messages.toList.iterator 
   } 
   // Take a sorted list of all the partitionId messages
   val messages = rdd2.collect().head
   // All the task partitionIds are shared
   for((x, i) <- messages.view.zipWithIndex) assert(x.toString == i.toString)
 }
{code}
In this test, the desired `messages`(a.k.a rdd2.collect().head) should be ["0", "1", "2", "3"], but is "0" in reality.

{code:java}
//Create a hive table in sparksql
spark-sql> create table test_table(id varchar(5)) stored as textfile;

// Create a file under linux, the content is 1234567890

// Then load this file into this hive table
spark-sql> load data local inpath '/home/test_table' overwrite into table test_table;

// Query this table in sparksql
spark-sql> select * from test_table;
12345

// Modify the length of this field in hive
hive> alter table test_table change column id id varchar(10);

// Query this table in hive
hive> select * from test_table;
OK
1234567890

// Query this table in sparksql again
spark-sql> select * from test_table;
// The obtained id is still 12345, so the length modification does not take effect in SparkSQL
12345{code}

