def getOutputStream(path: String, conf: Configuration): FSDataOutputStream = {
  val dfsPath = new Path(path)
  val dfs = getFileSystemForPath(dfsPath, conf)
  // If the file exists and we have append support, append instead of creating a new file
  val stream: FSDataOutputStream = {
    if (dfs.isFile(dfsPath)) {
      if (dfs.getScheme.toLowerCase.contains("s3")){
        dfs.create(dfsPath)
      } else if (conf.getBoolean("dfs.support.append", true) || conf.getBoolean("hdfs.append.support", false) || dfs.isInstanceOf[RawLocalFileSystem]) {
        dfs.append(dfsPath)
      } else {
        throw new IllegalStateException("File exists and there is no append support!")
      }
    } else {
      dfs.create(dfsPath)
    }
  }
  stream
}
