      .version("3.6.0")
      .timeConf(TimeUnit.SECONDS)
      .checkValue(_ >= 0L, "Last Timeout must be >= 0 (and preferrably >= spark.dynamicAllocation.executorIdleTimeout)")
      .createWithDefault(60)
{code}



