spark-sql> SELECT from_json('{"a":1, "b":1691241070000}', 'a INT, b TIMESTAMP');
{"a":1,"b":+55563-04-19 18:06:40}

spark-sql> SELECT from_json('{"a":1, "b":1691241070000000}', 'a INT, b TIMESTAMP');
{"a":1,"b":-183707-06-27 20:24:24.251328}{code}

