      (n: Int) => { if (n >= 0) n + 1 else throw new SparkException("Must be positive number.") })

    val result = df.filter("c1 >= 0 and plusOne(c1) > 1 and plusOne(c1) < 3").collect()
    assert(result.size === 1)
  }
} 

