In one of my Spark jobs, I enabled *spark.excludeOnFailure.killExcludedExecutors=true* and *spark.excludeOnFailure=true*, but I found that the excluded executor was not killed. The logs contain the following error message:
{code:java}
Not attempting to kill executors on excluded host cdh-001 since allocation client is not defined.
{code}
I checked the relevant code and found that the reason is that the *healthTracker* is initialized before the *sc.schedulerBackend*, causing *sc.schedulerBackend* to be null when *healthTracker* is initialized.
{code:scala}
private def maybeCreateHealthTracker(sc: SparkContext): Option[HealthTracker] = {
  if (HealthTracker.isExcludeOnFailureEnabled(sc.conf)) {
    val executorAllocClient: Option[ExecutorAllocationClient] = sc.schedulerBackend match {
      case b: ExecutorAllocationClient => Some(b)
      case _ => None
    }
    Some(new HealthTracker(sc, executorAllocClient))
  } else {
    None
  }
} {code}

